import isEmpty from"lodash/isEmpty";const deParameterize=queryString=>{if(isEmpty(queryString)||queryString.length===1&&queryString.charAt(0)==="?"){return{}}if(queryString&&queryString.charAt(0)==="?"){queryString=queryString.substring(1)}const ary=queryString.split("&");let paramObj={};for(let keyPair in ary){paramObj[ary[keyPair].split("=")[0]]=ary[keyPair].split("=")[1]}return paramObj};export default deParameterize;